:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --primary: #6c5ce7;
  --primary-hover: #5a4bd1;
  --text: #f0f0f5;
  --text-muted: #b0b0c0;
  --accent: #00cec9;
  --error: #ff6b6b;
  --radius: 12px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] { display: none !important; }

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  padding: 2rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  width: 100%;
  max-width: 480px;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 0.25rem;
  text-align: center;
}

.subtitle {
  color: var(--text-muted);
  text-align: center;
  margin-bottom: 1.5rem;
  font-size: 1rem;
}

.field {
  margin-bottom: 1.25rem;
}

label {
  display: block;
  margin-bottom: 0.4rem;
  font-weight: 600;
  font-size: 1rem;
}

input {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1.125rem;
  border: 2px solid #3a3a55;
  border-radius: var(--radius);
  background: #1e1e2f;
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(0, 206, 201, 0.3);
}

input:hover {
  border-color: #5a5a7a;
}

button {
  width: 100%;
  padding: 0.9rem;
  font-size: 1.125rem;
  font-weight: 700;
  color: #fff;
  background: var(--primary);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  margin-top: 0.5rem;
}

button:hover {
  background: var(--primary-hover);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.98);
}

.result {
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid #3a3a55;
}

.result h2 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  color: var(--accent);
}

.breakdown {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
  gap: 0.5rem;
}

.breakdown li {
  background: #1e1e2f;
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  font-size: 1rem;
  display: flex;
  justify-content: space-between;
  border-left: 3px solid var(--primary);
}

.breakdown li .denom {
  font-weight: 600;
}

.breakdown li .count {
  color: var(--accent);
  font-weight: 700;
}

.error {
  color: var(--error);
  margin-top: 1rem;
  text-align: center;
  font-weight: 600;
}

@media (max-width: 400px) {
  body { font-size: 16px; padding: 0.5rem; }
  .card { padding: 1.5rem; }
  h1 { font-size: 1.5rem; }
  .breakdown { grid-template-columns: 1fr; }
}

const DENOMINATIONS = [20, 10, 5, 2, 1, 0.5, 0.2, 0.1, 0.05];

const form = document.getElementById('change-form');
const priceInput = document.getElementById('price');
const paidInput = document.getElementById('paid');
const resultDiv = document.getElementById('result');
const changeSpan = document.getElementById('change-amount');
const breakdownList = document.getElementById('breakdown');
const errorP = document.getElementById('error');

function formatCurrency(amount) {
  return '\u00A3' + amount.toFixed(2);
}

function calculateChange(price, paid) {
  let change = Math.round((paid - price) * 100) / 100;
  if (change < 0) return null;
  const counts = [];
  for (const denom of DENOMINATIONS) {
    const denomCents = Math.round(denom * 100);
    const changeCents = Math.round(change * 100);
    const count = Math.floor(changeCents / denomCents);
    if (count > 0) {
      counts.push({ denom, count });
      change = (changeCents - count * denomCents) / 100;
    }
  }
  return counts;
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  errorP.hidden = true;
  resultDiv.hidden = true;

  const price = parseFloat(priceInput.value);
  const paid = parseFloat(paidInput.value);

  if (isNaN(price) || isNaN(paid)) {
    errorP.textContent = 'Please enter valid numbers for price and amount paid.';
    errorP.hidden = false;
    return;
  }
  if (price < 0 || paid < 0) {
    errorP.textContent = 'Price and amount paid must be non-negative.';
    errorP.hidden = false;
    return;
  }
  if (paid < price) {
    errorP.textContent = 'Amount paid must be at least the price.';
    errorP.hidden = false;
    return;
  }

  const change = Math.round((paid - price) * 100) / 100;
  changeSpan.textContent = formatCurrency(change);
  breakdownList.innerHTML = '';

  if (change === 0) {
    const li = document.createElement('li');
    li.textContent = 'No change needed.';
    breakdownList.appendChild(li);
  } else {
    const counts = calculateChange(price, paid);
    if (counts) {
      for (const { denom, count } of counts) {
        const li = document.createElement('li');
        const denomSpan = document.createElement('span');
        denomSpan.className = 'denom';
        denomSpan.textContent = formatCurrency(denom);
        const countSpan = document.createElement('span');
        countSpan.className = 'count';
        countSpan.textContent = '\u00D7 ' + count;
        li.appendChild(denomSpan);
        li.appendChild(countSpan);
        breakdownList.appendChild(li);
      }
    }
  }

  resultDiv.hidden = false;
});
